const jogos = $('Code Explode Jogos').all();
const selecoes = $('Get many Seleções').all();

const aliases = {
  'usa': 'united states',
  'korea republic': 'south korea',
  'türkiye': 'turkey',
  "côte d'ivoire": 'ivory coast',
  'cabo verde': 'cape verde',
  'ir iran': 'iran',
  'congo dr': 'dr congo',
  'czechia': 'czech republic',
};

function normalizar(nome) {
  if (!nome) return null;
  return aliases[nome.trim().toLowerCase()] || nome.trim().toLowerCase();
}

// mapa nome -> uuid
const mapa = {};

for (const s of selecoes) {
  if (s.json.nome && s.json.id) {
    mapa[normalizar(s.json.nome)] = s.json.id;
  }
}

const naoEncontrados = [];

const resultado = jogos.map(item => {
  const jogo = item.json;

  const timeA = mapa[normalizar(jogo.homeTeam)] ?? null;
  const timeB = mapa[normalizar(jogo.awayTeam)] ?? null;

  if (!timeA || !timeB) {
    naoEncontrados.push({
      homeTeam: jogo.homeTeam,
      awayTeam: jogo.awayTeam,
      timeAEncontrado: !!timeA,
      timeBEncontrado: !!timeB,
    });
  }

  return {
    json: {
      api_id: jogo.id,
      rodada: jogo.stage ?? null,

      // 🔥 SEMPRE EXISTEM (mesmo que null)
      time_a_id: timeA,
      time_b_id: timeB,

      data_jogo: jogo.kickoffUtc ?? null,

      placar_a:
        jogo.homeScore !== undefined ? jogo.homeScore : null,

      placar_b:
        jogo.awayScore !== undefined ? jogo.awayScore : null,

      encerrado:
        jogo.homeScore != null &&
        jogo.awayScore != null,
    },
  };
});

console.log('Total jogos:', resultado.length);
console.log('Não encontrados:', naoEncontrados);

return resultado;

